const UI=(()=>{const t=document.getElementById("output-text"),e=document.getElementById("wave");return{setSpeaking:function(n){t.textContent=n,t.classList.add("speaking"),e.classList.add("active")},setIdle:function(n="Menunggu panggilan..."){t.textContent=n,t.classList.remove("speaking"),e.classList.remove("active")},setLoading:function(t,e){const n=document.getElementById("btn-"+t);e?(n.innerHTML='<span class="spinner"></span>Loading...',n.disabled=!0):n.disabled=!1},addLog:function(t,e="tts"){const n=(new Date).toTimeString().slice(0,8),s="mic"===e?"🎤":"err"===e?"❌":"🔊";document.querySelectorAll(".log-container").forEach((a=>{const i=document.createElement("div");for(i.className="log-entry",i.innerHTML=`<span class="log-time">${n}</span><span class="log-msg ${e}">${s} ${t}</span>`,a.prepend(i);a.children.length>25;)a.removeChild(a.lastChild)}))},setMicState:function(t){const e=document.getElementById("mic-btn"),n=document.getElementById("mic-status");t?(e.classList.add("listening"),n.textContent="🔴 Mendengarkan... (aktif)"):(e.classList.remove("listening"),n.textContent="Klik mic untuk mulai dengarkan")},setTranscript:function(t,e=!1){const n=document.getElementById("mic-transcript");n.textContent=t,e?n.classList.add("active"):n.classList.remove("active")}}})();